    public static void main(String[] args) {
        SpringApplication.run(PaymentServiceApplication.class, args);
    }
}

// ...is equivalent to writing all three explicitly:
@Configuration            // can declare @Bean methods here
@EnableAutoConfiguration  // auto-configure beans from the classpath
@ComponentScan            // scan this package + sub-packages for @Component, @Service ...
public class PaymentServiceApplication { /* ... */ }

// Need control? Use attributes instead of splitting it apart:
@SpringBootApplication(exclude = DataSourceAutoConfiguration.class)
public class CustomApplication { /* DB auto-config skipped */ }
