// 1) pom.xml: spring-boot-starter-actuator
// 2) application.properties:
//    management.endpoints.web.exposure.include=health,info,metrics
//    management.endpoint.health.show-details=always

@Component
class DatabaseHealthIndicator implements HealthIndicator {
    private final DataSource dataSource;
    DatabaseHealthIndicator(DataSource dataSource) { this.dataSource = dataSource; }

    @Override
    public Health health() {
        try (var conn = dataSource.getConnection()) {
            return conn.isValid(2)
                ? Health.up().withDetail("db", "reachable").build()
                : Health.down().withDetail("db", "invalid connection").build();
        } catch (Exception e) {
            return Health.down(e).build();
        }
    }
}
// GET /actuator/health  ->  {"status":"UP","components":{"databaseHealth":{...}}}
```

